const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const chengdu = ee.Geometry.Point([104.06, 30.67]).buffer(10000); // 10km radius
    const suining = ee.Geometry.Point([105.57, 30.51]).buffer(10000); // 10km radius
    const startDate = '2001-01-01';
    const endDate = '2023-12-31';
    const band = 'Optical_Depth_055';
    const scaleFactor = 0.001;

    // 2. Data Acquisition
    const collection = ee.ImageCollection('MODIS/061/MOD04_L2')
        .filterDate(startDate, endDate)
        .select(band);

    // 3. Data Availability Check
    const chengduCol = collection.filterBounds(chengdu);
    const suiningCol = collection.filterBounds(suining);

    const chengduSize = chengduCol.size().getInfo();
    const suiningSize = suiningCol.size().getInfo();

    if (chengduSize === 0 || suiningSize === 0) {
        console.log(`Chengdu image count: ${chengduSize}`);
        console.log(`Suining image count: ${suiningSize}`);
        console.log("No images found for one or both locations in the specified date range.");
        console.log("A"); // C1
        return;
    }
    console.log(`Image count (Chengdu): ${chengduSize}`);
    console.log(`Image count (Suining): ${suiningSize}`);

    // 4. Processing & Calculation
    const calculateMeanAOD = (geometry) => {
        const meanImage = collection
            .filterBounds(geometry)
            .mean()
            .multiply(scaleFactor)
            .rename('meanAOD');

        // AOD must be non-negative.
        const validAOD = meanImage.updateMask(meanImage.gte(0));

        const stats = validAOD.reduceRegion({
            reducer: ee.Reducer.mean().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: geometry,
            scale: 5000, // Use a larger scale for regional stats to avoid timeout
            maxPixels: 1e9
        });
        return stats;
    };

    const chengduStats = calculateMeanAOD(chengdu).getInfo();
    const suiningStats = calculateMeanAOD(suining).getInfo();

    // 5. Validation & Final Answer
    const chengduAOD = chengduStats.meanAOD;
    const chengduCount = chengduStats.meanAOD_count;
    const suiningAOD = suiningStats.meanAOD;
    const suiningCount = suiningStats.meanAOD_count;

    console.log(`Chengdu Mean AOD: ${chengduAOD ? chengduAOD.toFixed(3) : 'N/A'}, Valid Pixels: ${chengduCount}`);
    console.log(`Suining Mean AOD: ${suiningAOD ? suiningAOD.toFixed(3) : 'N/A'}, Valid Pixels: ${suiningCount}`);

    if (chengduCount === 0 || suiningCount === 0) {
        console.log("No valid pixels found after processing for one or both locations.");
        console.log("B"); // C2
        return;
    }

    if (chengduAOD === null || suiningAOD === null || isNaN(chengduAOD) || isNaN(suiningAOD)) {
        console.log("Calculation failed, resulting in null or NaN values.");
        console.log("C"); // C3
        return;
    }

    if (chengduAOD > suiningAOD) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during Earth Engine initialization or analysis.');
        console.error(e);
        console.log("D");
    }
}

initEE();
